def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", type=Path, default=DEFAULT)
    parser.add_argument("--output", type=Path, default=DEFAULT)
    args = parser.parse_args()
    doc = Document(args.input)
    for index, (old_start, revised) in EDITS.items():
        paragraph = doc.paragraphs[index]
        original = paragraph.text
        if original == revised:
            continue
        if not original.startswith(old_start):
            raise ValueError(f"Párrafo {index} cambió: {original[:100]!r}")
        paragraph.text = revised
    doc.core_properties.title = "Comparación de procesadores RISC-V RV32I con Branch Target Buffer"
    args.output.parent.mkdir(parents=True, exist_ok=True)
    doc.save(args.output)
    print(args.output)


if __name__ == "__main__":
    main()
